                    if level == -1:
                        sub_diff = difference(value1, value2, level)
                    else:
                        sub_diff = difference(value1, value2, level - 1)
                    if sub_diff:
                        result[key] = sub_diff
            else:
                # Not both dicts, so just compare values
                if value1 != value2:
                    result[key] = value1

    return result

