def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    def _generate_default_schema_for_resource(resource):
        """Generate a default observer schema for a single Kubernetes resource.

        Args:
            resource: The Kubernetes resource definition

        Returns:
            A dictionary representing the default observer schema, or None if
            the resource type is not supported.
        """
        if not isinstance(resource, dict):
            return None

        kind = resource.get('kind')
        if not kind:
            return None

        # Default schema: observe the status and metadata of the resource
        default_schema = {
            'status': {
                'phase': None,
                'conditions': []
            },
            'metadata': {
                'name': None,
                'namespace': None,
                'labels': {}
            }
        }

        # Add resource-specific fields based on kind
        if kind == 'Deployment':
            default_schema['status']['replicas'] = None
            default_schema['status']['ready_replicas'] = None
            default_schema['status']['available_replicas'] = None
            default_schema['status']['updated_replicas'] = None
        elif kind == 'StatefulSet':
            default_schema['status']['replicas'] = None
            default_schema['status']['ready_replicas'] = None
            default_schema['status']['current_replicas'] = None
            default_schema['status']['updated_replicas'] = None
        elif kind == 'DaemonSet':
            default_schema['status']['desired_number_scheduled'] = None
            default_schema['status']['current_number_scheduled'] = None
            default_schema['status']['number_ready'] = None
            default_schema['status']['number_available'] = None
        elif kind == 'Pod':
            default_schema['status']['phase'] = None
            default_schema['status']['pod_ip'] = None
            default_schema['status']['host_ip'] = None
            default_schema['status']['container_statuses'] = []
        elif kind == 'Service':
            default_schema['spec']['type'] = None
            default_schema['spec']['cluster_ip'] = None
            default_schema['spec']['ports'] = []
        elif kind == 'Ingress':
            default_schema['status']['load_balancer'] = {}
        elif kind == 'ConfigMap':
            default_schema['data'] = {}
        elif kind == 'Secret':
            default_schema['data'] = {}
        elif kind == 'PersistentVolumeClaim':
            default_schema['status']['phase'] = None
            default_schema['status']['capacity'] = {}
        elif kind == 'Job':
            default_schema['status']['succeeded'] = None
            default_schema['status']['failed'] = None
            default_schema['status']['active'] = None
        elif kind == 'CronJob':
            default_schema['status']['last_schedule_time'] = None
            default_schema['status']['last_successful_time'] = None

        return default_schema
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        return

    manifest = app.spec.manifest
    if not isinstance(manifest, dict):
        return

    # Get or create the observer schema section
    if not hasattr(app.spec, 'observer_schema'):
        app.spec.observer_schema = {}
    observer_schema = app.spec.observer_schema

    # Iterate through each resource in the manifest
    for resource_name, resource in manifest.items():
        # Skip if a custom observer schema is already specified for this resource
        if resource_name in observer_schema:
            continue

        # Generate default observer schema for this resource
        default_schema = _generate_default_schema_for_resource(resource)
        if default_schema is not None:
            observer_schema[resource_name] = default_schema

