def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, (int, str)):
        raise TypeError("version must be an integer or string")

    # Check if version exists in inventory
    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory")

    version_data = inventory[version]

    # Initialize the result dictionary
    logical_path_map = {}

    # Process the version data to build the map
    # Assuming version_data is a dictionary mapping logical paths to content files
    # or a list of such mappings
    if isinstance(version_data, dict):
        for logical_path, content_files in version_data.items():
            if not isinstance(logical_path, str):
                raise TypeError(f"Logical path must be a string, got {type(logical_path)}")
            if not isinstance(content_files, (list, tuple, set)):
                raise TypeError(f"Content files must be a list, tuple, or set, got {type(content_files)}")
            logical_path_map[logical_path] = set(content_files)
    elif isinstance(version_data, (list, tuple)):
        # If it's a list of tuples or lists: [(logical_path, content_files), ...]
        for item in version_data:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise ValueError(f"Each item in version data must be a pair of (logical_path, content_files), got {item}")
            logical_path, content_files = item
            if not isinstance(logical_path, str):
                raise TypeError(f"Logical path must be a string, got {type(logical_path)}")
            if not isinstance(content_files, (list, tuple, set)):
                raise TypeError(f"Content files must be a list, tuple, or set, got {type(content_files)}")
            logical_path_map[logical_path] = set(content_files)
    else:
        raise TypeError(f"Unsupported version data type: {type(version_data)}")

    return logical_path_map

