def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces["error"]:
        return pieces["error"]

    style = style or "pep440"

    if style == "pep440-legacy":
        # was included only in old _version.py
        raise ValueError("pep440-legacy not supported")

    if style == "pep440":
        rendered = pieces["version"]

        if pieces["distance"] is not None:
            rendered += ".post%d" % pieces["distance"]

        if pieces["closest-tag"] is not None:
            rendered += "+" + pieces["closest-tag"]
        else:
            rendered += "+" + pieces["date"]
    elif style == "git-describe":
        rendered = pieces["closest-tag"]
        if pieces["distance"]:
            rendered += "-d%d" % pieces["distance"]
        if pieces["dirty"]:
            rendered += "-dirty"
    elif style == "short":
        rendered = pieces["short"]
    elif style == "branch-abbrev":
        rendered = pieces["branch"]
    elif style == "date":
        rendered = pieces["date"]
    else:
        raise ValueError("unknown style '%s'" % style)

    return rendered

