def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Iterate through the hierarchy
    for obj in self.hierarchy:
        num_objects += 1
        is_valid = True

        if validate_objects:
            # Check if the object is valid
            if not obj.is_valid():
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj} is not valid")

        if check_digests:
            # Check if the digest is correct
            if not obj.check_digest():
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj} has incorrect digest")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

