def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple")

        # Assume self has attributes:
        # self.root_inventory: dict mapping path -> digest
        # self.version_inventories: dict mapping version_dir -> dict mapping path -> digest
        # self.content_digests: dict mapping path -> set of digests (or similar)

        # We'll build a record of content digests that differ from root inventory
        # and validate that each version has an inventory.

        # Initialize a structure to track differing digests
        # self.differing_digests = {}  # path -> set of (version, digest)

        # For each version directory, check if inventory exists
        for version_dir in version_dirs:
            if not isinstance(version_dir, str):
                raise TypeError(f"version_dir must be a string, got {type(version_dir)}")

            # Check if inventory for this version exists
            # Assume self.version_inventories is a dict: version_dir -> inventory dict
            if not hasattr(self, 'version_inventories'):
                self.version_inventories = {}

            if version_dir not in self.version_inventories:
                # No inventory for this version - this is a SHOULD, so maybe log a warning
                # But for now, we can just note it
                pass

            # If inventory exists, compare with root inventory
            if version_dir in self.version_inventories:
                version_inv = self.version_inventories[version_dir]
                if not isinstance(version_inv, dict):
                    raise TypeError(f"Inventory for version {version_dir} must be a dict")

                # Compare with root inventory
                if not hasattr(self, 'root_inventory'):
                    self.root_inventory = {}

                if not hasattr(self, 'differing_digests'):
                    self.differing_digests = {}

                for path, digest in version_inv.items():
                    if path in self.root_inventory:
                        root_digest = self.root_inventory[path]
                        if digest != root_digest:
                            if path not in self.differing_digests:
                                self.differing_digests[path] = set()
                            self.differing_digests[path].add((version_dir, digest))
                    else:
                        # Path not in root inventory, record it
                        if path not in self.differing_digests:
                            self.differing_digests[path] = set()
                        self.differing_digests[path].add((version_dir, digest))

        # Return the differing digests or some result
        return getattr(self, 'differing_digests', {})

