    parsed = {}
    remaining = list(unparsed_arguments)
    for name, parser in subparsers.items():
        try:
            args, rest = parser.parse_known_args(remaining)
            parsed[name] = args
            remaining = rest
        except SystemExit:
            # If a subparser exits (e.g., due to --help or error), skip it
