def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("At least one base class is required")

    # If explicit metaclass is provided, use it
    if explicit_mc is not None:
        return explicit_mc

    # Find the most derived metaclass among the bases
    metaclasses = []
    for base in bases:
        if isinstance(base, type):
            metaclasses.append(type(base))
        else:
            # If base is not a class, try to get its metaclass
            try:
                metaclasses.append(type(base))
            except TypeError:
                pass

    if not metaclasses:
        return type

    # Find the most derived metaclass
    # A metaclass M1 is more derived than M2 if M1 is a subclass of M2
    most_derived = metaclasses[0]
    for mc in metaclasses[1:]:
        if issubclass(mc, most_derived):
            most_derived = mc

    return most_derived

