def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict

    from xml.etree import ElementTree
    if not document or not isinstance(document, str):
        raise ValueError("Document must be a non-empty string")

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except json.JSONDecodeError:
        pass

    # Try XRD (XML)
    try:
        root = ElementTree.fromstring(document)
        result = {}

        # XRD structure: <XRD xmlns="http://docs.oasis-open.org/webfinger/xrd">
        # We need to handle namespaces
        ns = {'xrd': 'http://docs.oasis-open.org/webfinger/xrd'}

        # Get subject
        subject_elem = root.find('xrd:subject', ns)
        if subject_elem is not None:
            result['subject'] = subject_elem.text

        # Get aliases
        aliases = []
        for alias_elem in root.findall('xrd:alias', ns):
            if alias_elem.text:
                aliases.append(alias_elem.text)
        if aliases:
            result['aliases'] = aliases

        # Get links
        links = []
        for link_elem in root.findall('xrd:link', ns):
            link = {}
            for attr in link_elem.attrib:
                # Remove namespace from attribute name if present
                if ':' in attr:
                    attr_name = attr.split(':')[-1]
                else:
                    attr_name = attr
                link[attr_name] = link_elem.attrib[attr]
            links.append(link)
        if links:
            result['links'] = links

        return result
    except ElementTree.ParseError:
        pass

    raise ValueError("Document is not valid JSON or XRD")

