def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import json

    import urllib.error

    from typing import Optional
    if not handle or not isinstance(handle, str):
        return None

    # Normalize the handle
    handle = handle.strip()

    # If it's already a full URL, use it as is
    if handle.startswith("http://") or handle.startswith("https://"):
        url = handle
    else:
        # Assume it's a domain or user@domain format
        if "@" in handle:
            user, domain = handle.split("@", 1)
            # RFC 7033: .well-known/webfinger?resource=acct:user@domain
            url = f"https://{domain}/.well-known/webfinger?resource=acct:{user}@{domain}"
        else:
            # Just a domain, try to get the webfinger document for the domain itself
            url = f"https://{handle}/.well-known/webfinger"

    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.status == 200:
                content_type = response.headers.get('Content-Type', '')
                if 'application/json' in content_type or 'application/jrd+json' in content_type:
                    data = response.read().decode('utf-8')
                    # Validate it's valid JSON
                    json.loads(data)
                    return data
                else:
                    return None
            else:
                return None
    except Exception:
        return None

