def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    # Define the path to the plugin spec file
    spec_file = os.path.join(plugin_dir, 'plugin_spec.json')
    spec_file_yaml = os.path.join(plugin_dir, 'plugin_spec.yaml')
    spec_file_yml = os.path.join(plugin_dir, 'plugin_spec.yml')

    # Try to load the spec from JSON first
    if os.path.exists(spec_file):
        try:
            with open(spec_file, 'r') as f:
                spec = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from JSON: {e}")
    # Then try YAML
    elif os.path.exists(spec_file_yaml):
        try:
            with open(spec_file_yaml, 'r') as f:
                spec = yaml.safe_load(f)
        except (yaml.YAMLError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from YAML: {e}")
    elif os.path.exists(spec_file_yml):
        try:
            with open(spec_file_yml, 'r') as f:
                spec = yaml.safe_load(f)
        except (yaml.YAMLError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from YAML: {e}")
    else:
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    # Flatten the dictionary
    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                # For lists, we can either flatten them or keep them as is
                # Here we'll keep them as is, but if you want to flatten lists, you can modify this
                items.append((new_key, v))
            else:
                items.append((new_key, v))
        return dict(items)

